Running command: cd /workspace && cat > test_blosclz4.c << 'EOF'
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "blosclz.h"
int main(int argc, char**argv) {
  int length = atoi(argv[1]);
  int maxout = length;
  unsigned char *input = malloc(length);
  unsigned char *output = malloc(maxout + 1);
  srand(1);
  for (int i = 0; i < length; i++) input[i] = rand() & 0xff;
  // probe region is [length-length/4, length-length/4+min(length/4,4096)]
  int start = length - length/4;
  int probe_len = (length/4 < 4096) ? length/4 : 4096;
  memset(input + start, 0, probe_len);
  int r = blosclz_compress(9, input, length, output, maxout, 1);
  printf("length=%d result=%d maxout=%d\n", length, r, maxout);
  return 0;
}
EOF
gcc -fsanitize=address -g -O1 -I./repo-vul/src-vul/c-blosc/blosc test_blosclz4.c ./repo-vul/src-vul/c-blosc/build/blosc/libblosc.a -o test_blosclz4 -lpthread 2>&1 | tail -5
export ASAN_OPTIONS=detect_leaks=0
for L in 100000 150000 200000 300000 500000; do echo "=== $L ==="; ./test_blosclz4 $L 2>&1 | grep -E "length=|ERROR|WRITE|overflow|SUMMARY" | head -5; done

